const {chromium}=require('playwright'),fs=require('fs'),path=require('path'),assert=require('node:assert/strict');
(async()=>{const b=await chromium.launch({channel:'chrome',headless:true});try{const p=await b.newPage({viewport:{width:390,height:844}});await p.route('https://review.test/**',r=>r.fulfill({contentType:'text/html',body:'<main></main>'}));await p.goto('https://review.test');
const root=path.join(__dirname,'../web');for(const f of ['00-core','05-primitives'])await p.addStyleTag({content:fs.readFileSync(path.join(root,'css',f+'.css'),'utf8')});await p.addScriptTag({content:fs.readFileSync(path.join(root,'js/05-components.js'),'utf8')});
await p.evaluate(()=>{
 window.artifact={id:'0123456789abcdef',title:'Research report'};window.records=[];window.requests=[];window.loss=true;window.discussed=[];
 window.fetch=async(url,options={})=>{if(options.method==='POST'){const request=JSON.parse(options.body);requests.push(request);if(!records.some(r=>r.id===request.request_id))records.push({id:request.request_id,revision:'a'.repeat(64),state:request.state,note:request.note,start:request.start,end:request.end,at:new Date().toISOString()});if(loss){loss=false;throw Error('Connection lost after saving');}}
 return{ok:true,json:async()=>({record_version:String(records.length),revision:'a'.repeat(64),state:records.at(-1)?.state||'not_requested',entries:structuredClone(records)})};};
 document.querySelector('main').append(artifactReviewControls(artifact,'a'.repeat(64),2,ref=>discussed.push(ref)));
});
await p.getByText('Review · Not reviewed').click();await p.getByLabel('Review decision').selectOption('changes_requested');await p.getByLabel('Review notes').fill('Cite evidence for this conclusion.');await p.getByText('Specific lines').click();await p.getByLabel('First reviewed line').fill('2');await p.getByLabel('Last reviewed line').fill('4');await p.getByRole('button',{name:'record and draft request'}).click();await p.getByText('Connection lost after saving').waitFor();assert.equal(await p.evaluate(()=>discussed.length),0);
await p.getByRole('button',{name:'record and draft request'}).click();await p.getByRole('button',{name:'recorded',exact:true}).waitFor();const result=await p.evaluate(()=>({requests,records,discussed}));assert.equal(result.records.length,1);assert.equal(result.requests[0].request_id,result.requests[1].request_id);assert.equal(result.discussed[0].revision,'a'.repeat(64));assert.equal(result.discussed[0].reviewStart,2);assert.equal(result.discussed[0].reviewEnd,4);assert.equal(await p.getByRole('button',{name:'recorded'}).isDisabled(),true);
for(const width of [320,390,1440]){await p.setViewportSize({width,height:844});assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);}
await p.setViewportSize({width:390,height:844});await p.evaluate(()=>document.documentElement.dataset.theme='jarvis');await p.screenshot({path:'/tmp/manifest-artifact-review-phone.png'});
// A late result from a closed pane must not draft into another conversation.
await p.evaluate(()=>{records=[];document.querySelector('main').replaceChildren(artifactReviewControls(artifact,'a'.repeat(64),2,ref=>discussed.push(ref)));});await p.getByText('Review · Not reviewed').click();await p.getByLabel('Review decision').selectOption('changes_requested');await p.getByLabel('Review notes').fill('Another request');
await p.evaluate(()=>{const original=fetch;window.fetch=(...args)=>args[1]?.method==='POST'?new Promise(resolve=>window.finish=async()=>resolve(await original(...args))):original(...args);});await p.getByRole('button',{name:'record and draft request'}).click();await p.evaluate(()=>{document.querySelector('main').replaceChildren();finish();});await p.waitForTimeout(30);assert.equal(await p.evaluate(()=>discussed.length),1);
await p.evaluate(()=>{document.querySelector('main').append(artifactReviewControls(artifact,'a'.repeat(64),2,null));});await p.getByLabel('Review notes').evaluate(e=>e.closest('details').open=true);await p.getByLabel('Review notes').fill('Unsent review draft');await p.evaluate(()=>document.querySelector('main').replaceChildren(artifactReviewControls(artifact,'a'.repeat(64),2,null)));assert.equal(await p.getByLabel('Review notes').inputValue(),'Unsent review draft');
console.log('PASS revision-specific review, lost-response retry, range retention, duplicate-click prevention, detached-pane isolation, responsive layout.');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
